    if e.get('status') != 'DONE':
        continue
    conclusion = e.get('conclusion', '')
    metrics = e.get('metrics', {}) or {}

    # Extract key numbers - different metrics formats exist
    key_nums = {}
    if isinstance(metrics, dict):
        # Check for per_gen format
        if 'per_gen' in metrics:
            per_gen = metrics['per_gen']
            if isinstance(per_gen, dict):
                gens = sorted(per_gen.keys())
                if gens:
                    last_gen = gens[-1]
                    last_data = per_gen[last_gen]
                    if isinstance(last_data, dict):
                        key_nums = {f'{last_gen}_{k}': v for k, v in list(last_data.items())[:5]}
        else:
            # Flat format - grab last gen metrics
            flat_keys = sorted([k for k in metrics.keys() if k.startswith('gen')])
            # Get the highest gen number
            gen_nums = set()
            for k in flat_keys:
                m = re.match(r'gen(\d+)', k)
