                    if k.startswith(f'gen{max_gen}_'):
                        key_nums[k] = v
            # Also grab gen0 ppl for reference
            if 'gen0_ppl' in metrics:
                key_nums['gen0_ppl'] = metrics['gen0_ppl']

    print(f'{eid} ({conclusion}): {key_nums}')
